  /* ---------- stack rows: endless, draggable, resume at default speed ---------- */
  var mqs=[].map.call(document.querySelectorAll('.mq'),function(mq,i){
    var tr=mq.querySelector('.track'),n=rows[i].length;
    var R={mq:mq,tr:tr,n:n,x:0,W:1,spd:parseFloat(mq.style.getPropertyValue('--spd'))||55,dir:mq.classList.contains('rev')?1:-1,v:0,drag:false,lx:0,lt:0,vs:0};
    mq.addEventListener('pointerdown',function(e){if(e.button!==0)return;R.drag=true;R.lx=e.clientX;R.lt=performance.now();R.vs=0;mq.classList.add('drag');try{mq.setPointerCapture(e.pointerId);}catch(_){}});
    mq.addEventListener('pointermove',function(e){if(!R.drag)return;var now=performance.now(),dx=e.clientX-R.lx,dtm=Math.max(1,now-R.lt);R.x+=dx;var inst=dx/dtm*1000;R.vs=R.vs*.7+inst*.3;R.lx=e.clientX;R.lt=now;});
    function up(){if(!R.drag)return;R.drag=false;mq.classList.remove('drag');
      /* a flick carries on briefly, then eases into the row's own speed and direction */
      var idle=performance.now()-R.lt>90;R.v=idle?0:Math.max(-2600,Math.min(2600,R.vs));}
    mq.addEventListener('pointerup',up);mq.addEventListener('pointercancel',up);mq.addEventListener('lostpointercapture',up);
    return R;
  });
  function measureRows(){mqs.forEach(function(R){var c=R.tr.children;if(c.length>R.n){var W=c[R.n].offsetLeft-c[0].offsetLeft;if(W>0){R.W=W;}}if(!R.v&&!R.drag)R.v=R.dir*R.W/R.spd*(reduced?0:1);});}
  measureRows();if(document.fonts&&document.fonts.ready)document.fonts.ready.then(measureRows);
  function stepRows(dt){mqs.forEach(function(R){
    if(!R.drag){var vd=reduced?0:R.dir*R.W/R.spd;R.v+=(vd-R.v)*(1-Math.exp(-dt*2.2));R.x+=R.v*dt;}
    var W=R.W;R.x=((R.x%W)+W)%W-W;   /* keep x in [-W,0): the copies make the wrap invisible */
    R.tr.style.transform='translate3d('+R.x.toFixed(2)+'px,0,0)';
  });}

